package dev.joaomendonca.agendapro.settings.application;import dev.joaomendonca.agendapro.settings.api.*;import dev.joaomendonca.agendapro.settings.domain.*;import dev.joaomendonca.agendapro.settings.infrastructure.*;import dev.joaomendonca.agendapro.shared.security.AuthenticatedTenantProvider;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class SettingsService{private final TenantSettingsRepository repo;private final AuthenticatedTenantProvider tenant;public SettingsService(TenantSettingsRepository r,AuthenticatedTenantProvider t){repo=r;tenant=t;}@Transactional public SettingsResponse get(){return map(repo.findById(tenant.tenantId()).orElseGet(()->repo.save(new TenantSettings(tenant.tenantId()))));}@Transactional public SettingsResponse update(SettingsRequest r){var s=repo.findById(tenant.tenantId()).orElseGet(()->new TenantSettings(tenant.tenantId()));s.update(r.businessName(),r.phone(),r.timezone(),r.currency(),r.bookingIntervalMinutes(),r.cancellationHours());return map(repo.save(s));}private SettingsResponse map(TenantSettings s){return new SettingsResponse(s.getBusinessName(),s.getPhone(),s.getTimezone(),s.getCurrency(),s.getBookingIntervalMinutes(),s.getCancellationHours());}}
